import os,pathlib,select,subprocess,time
def follow_rotation(path,rotate):
    path=pathlib.Path(path)
    if path.is_symlink() or not path.is_file() or not callable(rotate):raise ValueError('real file and rotation callback required')
    process=subprocess.Popen(['tail','-n','1','-F','--sleep-interval=.05','--max-unchanged-stats=1',str(path.absolute())],stdout=subprocess.PIPE,stderr=subprocess.DEVNULL)
    pending=bytearray()
    def line():
        deadline=time.monotonic()+3
        while time.monotonic()<deadline:
            if b'\n' in pending:
                end=pending.index(10)+1;value=bytes(pending[:end]);del pending[:end];return value
            ready,_,_=select.select([process.stdout],[],[],max(0,deadline-time.monotonic()))
            if ready:
                chunk=os.read(process.stdout.fileno(),4096)
                if not chunk:raise RuntimeError('tail exited before line')
                pending.extend(chunk)
                if len(pending)>8192:raise RuntimeError('bounded output exceeded')
        raise RuntimeError('tail follow deadline exceeded')
    try:
        before=line();rotate()
        after=line()
        while after.startswith(b'OLD-INODE:'):after=line()
        return {'before':before,'after':after}
    finally:
        if process.poll() is None:process.terminate()
        try:process.wait(timeout=1)
        except subprocess.TimeoutExpired:process.kill();process.wait(timeout=1)
        process.stdout.close()
